        parts = sys.stdin.readline().split()
        if parts[0] == '1':
            x = int(parts[1])
            if counts[x] == 0:
                current_count += 1
            counts[x] += 1
        elif parts[0] == '2':
            x = int(parts[1])
            counts[x] -= 1
            if counts[x] == 0:
                current_count -= 1
        elif parts[0] == '3':
            output.append(str(current_count))
    print('\n'.join(output))

